package in.asmj.ride.model;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.mapping.Document;import java.time.Instant;import java.util.ArrayList;import java.util.List;
@Document("safety_reports") public class SafetyReport {
 @Id private String id; private String rideId,userId,userName,type,details,status="OPEN",adminNote; private List<UploadedAsset> attachments=new ArrayList<>(); private Instant createdAt=Instant.now(),updatedAt=Instant.now();
 public String getId(){return id;} public String getRideId(){return rideId;} public void setRideId(String v){rideId=v;} public String getUserId(){return userId;} public void setUserId(String v){userId=v;} public String getUserName(){return userName;} public void setUserName(String v){userName=v;} public String getType(){return type;} public void setType(String v){type=v;} public String getDetails(){return details;} public void setDetails(String v){details=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;updatedAt=Instant.now();} public String getAdminNote(){return adminNote;} public void setAdminNote(String v){adminNote=v;updatedAt=Instant.now();} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} public List<UploadedAsset> getAttachments(){return attachments;} public void setAttachments(List<UploadedAsset> v){attachments=v==null?new ArrayList<>():v;}
}
